//! Fork-owned items split out of `agent_panel.rs` so upstream syncs don't
//! conflict on them (plan 038; generated by script/fork-split-items).

use super::*;

pub(super) fn project_auto_prompt_md_path(
    project: &Entity<Project>,
    require_existing_file: bool,
    cx: &App,
) -> Option<PathBuf> {
    let rel_path = util::rel_path::RelPath::from_unix_str("AUTO_PROMPT.md").ok()?;
    project
        .read(cx)
        .visible_worktrees(cx)
        .next()
        .and_then(|worktree| {
            let worktree = worktree.read(cx);

            if require_existing_file {
                let entry = worktree.entry_for_path(rel_path)?;
                if !entry.is_file() {
                    return None;
                }
            }

            Some(worktree.absolutize(rel_path))
        })
}

pub(super) fn open_global_auto_prompt(
    workspace: &mut Workspace,
    window: &mut Window,
    cx: &mut Context<Workspace>,
) {
    let path = paths::auto_prompt_file().clone();
    if !path.exists() {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).log_err();
        }
        std::fs::write(
            &path,
            BuiltInPrompt::AutoPromptSystemPrompt.default_content(),
        )
        .log_err();
    }
    workspace
        .open_abs_path(
            path,
            workspace::OpenOptions {
                focus: Some(true),
                ..Default::default()
            },
            window,
            cx,
        )
        .detach_and_log_err(cx);
}

pub(super) fn open_project_auto_prompt(
    workspace: &mut Workspace,
    window: &mut Window,
    cx: &mut Context<Workspace>,
) {
    if let Some(path) = project_auto_prompt_md_path(workspace.project(), false, cx) {
        workspace
            .open_abs_path(
                path,
                workspace::OpenOptions {
                    focus: Some(true),
                    ..Default::default()
                },
                window,
                cx,
            )
            .detach_and_log_err(cx);
    }
}

/// Upper bound on the number of parked continuation threads we keep live in
/// memory at once (issue 006). Each retained `ConversationView` subscribes to
/// the global `action_log`, so unbounded growth produces an N×M repaint
/// cascade on every file edit. Past this cap the oldest non-generating thread
/// is dropped from memory; its metadata stays in `ThreadMetadataStore` so the
/// user can reopen it from the sidebar.
pub(super) const MAX_RETAINED_THREADS: usize = 8;

impl AgentPanel {
    /// Start a foreground timer (every ~10s) that drains peer-agent-state
    /// notifications from `auto_prompt::peer_states` and pushes them into the
    /// active agent thread. This is the P2.3 "chat visibility" injection —
    /// remote agent states appear as muted notification cards in the
    /// conversation view. The task is held in `_notification_drain_task` so it
    /// lives for the panel's lifetime.
    ///
    /// Plan 015: also drains web steering replies, resolving them by session-id
    /// prefix to the correct thread and injecting via `send` + steering flag.
    ///
    /// Plan 026: (a) mirrors new thread entries to the board so the web
    /// Threads tab can render them, and (b) honors `!stop` / `!retry` reply
    /// commands by driving `AcpThread::cancel` / `retry` directly.
    ///
    /// Issue 016 part 2: also pumps `acp_thread::verdict`'s pending-close list,
    /// so TTL-expired external reviewer sessions are closed without needing
    /// an `App` handle inside `prune_expired`.
    pub(super) fn start_notification_drain(&mut self, cx: &mut Context<Self>) {
        let timer = cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(std::time::Duration::from_secs(10))
                    .await;

                // 1. Peer-state notifications → display-only in active thread.
                let notifications = auto_prompt::peer_states::drain_unseen_notifications();
                if !notifications.is_empty() {
                    this.update(cx, |panel, cx| {
                        if let Some(thread) = panel.active_agent_thread(cx) {
                            thread.update(cx, |thread, cx| {
                                for text in &notifications {
                                    thread.push_agent_board_notification(text.clone(), cx);
                                }
                            });
                        }
                    })
                    .ok();
                }

                // 2. Mirror new thread entries to the board (web Threads tab).
                this.update(cx, |panel, cx| {
                    panel.broadcast_new_thread_entries(cx);
                })
                .ok();

                // 3. Web steering replies → inject into target threads; `!stop`
                //    / `!retry` are control commands instead of prompts.
                let replies = auto_prompt::peer_states::drain_web_replies();
                if !replies.is_empty() {
                    this.update(cx, |panel, cx| {
                        for (session_prefix, text) in &replies {
                            let Some(thread) =
                                panel.thread_for_session_prefix(session_prefix, cx)
                            else {
                                log::warn!(
                                    "[agent_board] web reply for session prefix {session_prefix} has no matching thread — skipping"
                                );
                                continue;
                            };
                            let trimmed = text.trim();
                            match trimmed {
                                "!stop" => {
                                    thread.update(cx, |thread, cx| {
                                        thread.cancel(cx).detach();
                                    });
                                    log::info!(
                                        "[agent_board] web !stop → cancelled session {session_prefix}"
                                    );
                                }
                                "!retry" => {
                                    thread.update(cx, |thread, cx| {
                                        let future = thread.retry(cx);
                                        cx.background_executor()
                                            .spawn(async move {
                                                if let Err(error) = future.await {
                                                    log::warn!(
                                                        "[agent_board] web !retry failed: {error:#}"
                                                    );
                                                }
                                            })
                                            .detach();
                                    });
                                    log::info!(
                                        "[agent_board] web !retry → retrying session {session_prefix}"
                                    );
                                }
                                _ => {
                                    let text = text.clone();
                                    thread.update(cx, |thread, cx| {
                                        let reply_text =
                                            format!("🌐 REPLY:[{session_prefix}] {text}");
                                        let future = thread.send(vec![reply_text.into()], cx);
                                        cx.background_executor()
                                            .spawn(async move {
                                                if let Err(error) = future.await {
                                                    log::warn!(
                                                        "[agent_board] web reply send failed: {error:#}"
                                                    );
                                                }
                                            })
                                            .detach();
                                    });
                                    log::info!(
                                        "[agent_board] injected web reply for session prefix {session_prefix}"
                                    );
                                }
                            }
                        }
                    })
                    .ok();
                }

                // 4. Verdict ping-pong: close TTL-expired external reviewer
                //    sessions deferred by `verdict::prune_expired`.
                cx.update(acp_thread::verdict::drain_pending_closes);
            }
        });
        self._notification_drain_task = Some(timer);
    }

    /// Plan 026: mirror the tail of every conversation view's root thread to
    /// the board for the web Threads tab. Sends the last few entries every time
    /// the tail changes (new entry OR in-place growth of the last one); the
    /// worker upserts by `seq`, so re-sends replace rather than duplicate.
    /// Board-injected notifications are skipped — the mirror must never echo
    /// board content back to the board.
    pub(super) fn broadcast_new_thread_entries(&mut self, cx: &mut Context<Self>) {
        const TAIL: usize = 3;
        let views = self.conversation_views();
        for view in views {
            let Some(thread) = view.read(cx).root_thread(cx) else {
                continue;
            };
            let (session_id, title) = thread.read_with(cx, |thread, _| {
                (
                    thread.session_id().clone(),
                    thread.title().map(|t| t.to_string()),
                )
            });
            // Fingerprint = (entry count, hash of the last mirrored entry's
            // text). Equal fingerprints mean nothing new to send.
            let (len, fingerprint) = thread.read_with(cx, |thread, cx| {
                let len = thread.entries().len();
                let hash = thread
                    .entries()
                    .last()
                    .map(|entry| {
                        let mut hasher = std::collections::hash_map::DefaultHasher::new();
                        std::hash::Hash::hash(&entry.to_markdown(cx), &mut hasher);
                        std::hash::Hasher::finish(&hasher)
                    })
                    .unwrap_or(0);
                (len, hash)
            });
            if Some((len, fingerprint)) == self.thread_broadcast_tails.get(&session_id).copied() {
                continue;
            }
            self.thread_broadcast_tails
                .insert(session_id.clone(), (len, fingerprint));

            let start = len.saturating_sub(TAIL);
            let new_entries: Vec<auto_prompt::peer_states::ThreadEntry> =
                thread.read_with(cx, |thread, cx| {
                    thread
                        .entries()
                        .iter()
                        .enumerate()
                        .skip(start)
                        .filter_map(|(index, entry)| {
                            let role = match entry {
                                acp_thread::AgentThreadEntry::UserMessage(_) => "user",
                                acp_thread::AgentThreadEntry::AssistantMessage(_) => "assistant",
                                acp_thread::AgentThreadEntry::ToolCall(_) => "tool",
                                // Board-injected notifications would echo back
                                // to the board; elicitation/plan/compaction
                                // entries are local UI chrome.
                                _ => return None,
                            };
                            Some(auto_prompt::peer_states::ThreadEntry {
                                seq: index as u64,
                                role: role.to_string(),
                                text: entry.to_markdown(cx),
                            })
                        })
                        .collect()
                });
            if !new_entries.is_empty() {
                auto_prompt::peer_states::broadcast_thread_update(
                    &session_id.to_string(),
                    title.as_deref(),
                    &new_entries,
                );
            }
        }
    }

    pub fn set_auto_prompt_enabled(&mut self, enabled: bool) {
        self.auto_prompt_enabled = enabled;
    }

    /// Like [`external_thread`](Self::external_thread) but parks the new thread
    /// in `retained_threads` instead of making it the active base_view.
    ///
    /// Used by auto_prompt continuation threads so they generate in the
    /// background without replacing the view the user is currently looking
    /// at. The thread stays live and appears in the sidebar; the user can
    /// click into it when ready. Passing `true` for `focus` here has no
    /// effect — background threads never steal focus.
    pub(crate) fn external_thread_background(
        &mut self,
        agent_choice: Option<crate::Agent>,
        resume_thread_id: Option<ThreadId>,
        work_dirs: Option<PathList>,
        title: Option<SharedString>,
        initial_content: Option<AgentInitialContent>,
        source: AgentThreadSource,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Option<ThreadId> {
        if resume_thread_id.is_none() && !self.has_open_project(cx) {
            return None;
        }
        let agent = agent_choice.unwrap_or_else(|| self.selected_agent(cx));
        let thread = self.create_agent_thread_with_server(
            agent,
            None,
            resume_thread_id,
            work_dirs,
            title,
            initial_content,
            None,
            source,
            window,
            cx,
        );
        let thread_id = thread.conversation_view.read(cx).thread_id;
        self.insert_retained_thread(thread_id, thread.conversation_view, cx);
        cx.emit(AgentPanelEvent::ActiveViewChanged);
        cx.notify();
        Some(thread_id)
    }

    /// One-line summaries of sibling threads that are actively generating, for
    /// auto_prompt start-context. Idle/draft threads are skipped — a
    /// continuation prompt cares about concurrent work, not parked threads.
    ///
    /// `skip_view` must carry the entity id of any conversation view that is
    /// currently leased (being updated) on the call stack — reading it here
    /// would double-lease panic. In practice that is the dispatching view
    /// itself, which is the continuation target, not a sibling.
    pub(crate) fn active_thread_activity(
        &self,
        cx: &App,
        skip_view: Option<gpui::EntityId>,
    ) -> Vec<String> {
        let mut actives = Vec::new();
        for view in self.conversation_views() {
            if skip_view.is_some_and(|id| id == view.entity_id()) {
                continue;
            }
            let Some(thread_view) = view.read(cx).active_thread() else {
                continue;
            };
            let thread = thread_view.read(cx).thread.clone();
            let thread = thread.read(cx);
            if !matches!(thread.status(), acp_thread::ThreadStatus::Generating) {
                continue;
            }
            let title = thread
                .title()
                .map(|title| title.to_string())
                .unwrap_or_else(|| "untitled".to_string());
            let line = match crate::auto_prompt::last_assistant_snippet(
                thread.entries(),
                crate::auto_prompt::ACTIVITY_SNIPPET_MAX_CHARS,
                cx,
            ) {
                Some(snippet) => format!("{title}: {snippet}"),
                None => title,
            };
            actives.push(line);
        }
        actives
    }

    /// Number of agent threads currently `Generating`, across the active and
    /// retained conversation views. Used by the auto_prompt dispatch cap
    /// (issue 006 P2): background continuation chains must queue instead of
    /// stacking unbounded concurrent streams (each stream drives window-wide
    /// repaint pressure — the 3N-repaints/sec death spiral).
    ///
    /// `skip_view` excludes one conversation view from the count — pass the
    /// dispatching view's id when called from inside its update (reading it
    /// would double-lease), the same pattern as [`Self::active_thread_activity`].
    pub(crate) fn generating_thread_count(
        &self,
        cx: &App,
        skip_view: Option<gpui::EntityId>,
    ) -> usize {
        self.conversation_views()
            .iter()
            .filter(|view| {
                if skip_view.is_some_and(|id| id == view.entity_id()) {
                    return false;
                }
                view.read(cx).active_thread().is_some_and(|thread_view| {
                    matches!(
                        thread_view.read(cx).thread.read(cx).status(),
                        acp_thread::ThreadStatus::Generating
                    )
                })
            })
            .count()
    }

    /// Find an `AcpThread` by session-id prefix (Plan 015). Scans all active
    /// and retained conversation views, returning the first whose
    /// `session_id` starts with the given prefix. Logs a warning on collision
    /// (multiple matches).
    pub fn thread_for_session_prefix(&self, prefix: &str, cx: &App) -> Option<Entity<AcpThread>> {
        let mut matches = Vec::new();
        for view in self.conversation_views() {
            if let Some(thread) = view.read(cx).root_thread(cx) {
                let session_id = thread.read(cx).session_id().to_string();
                if session_id.starts_with(prefix) {
                    matches.push(thread);
                }
            }
        }
        match matches.len() {
            0 => None,
            1 => Some(matches.into_iter().next().unwrap()),
            n => {
                log::warn!(
                    "[agent_board] session prefix '{prefix}' matched {n} threads — using first"
                );
                Some(matches.into_iter().next().unwrap())
            }
        }
    }

    /// Whether a retained thread may be dropped from `retained_threads`
    /// without losing in-flight work. Busy threads (Generating, loading,
    /// generating a title or summary, or with queued messages) and threads
    /// that cannot be reloaded from their agent server must be kept —
    /// evicting them cancels their recovery chains (watchdog, auto_prompt
    /// tasks) and, for unloadable threads, loses the thread entirely.
    pub(super) fn is_thread_evictable(
        &self,
        conversation_view: &Entity<ConversationView>,
        cx: &App,
    ) -> bool {
        let view = conversation_view.read(cx);
        if view.has_pending_selections() || view.has_saved_input() {
            return false;
        }
        let Some(thread_view) = view.root_thread_view() else {
            return false;
        };
        let thread_view = thread_view.read(cx);
        let acp_thread = thread_view.thread.read(cx);
        // Only consider truly-idle, loadable threads for cleanup.
        if !acp_thread.connection().supports_load_session() || !acp_thread.is_idle_for_retention() {
            return false;
        }
        // `is_loading_contents` covers the window between `send()` and
        // the turn actually starting: the editor's message (including
        // mention resolutions such as the ThreadSummary follow-up) is
        // being resolved into content blocks. The thread reports Idle
        // during this window, so without this guard the thread can be
        // evicted while its summary/content is still loading — which is the
        // "new thread disappears while summary is loading" bug.
        //
        // Note: we intentionally do NOT guard on `_auto_prompt_task` —
        // that task is the orchestration LLM call, and cancelling it on
        // eviction merely stops the auto_prompt chain for an otherwise
        // idle thread; it does not lose user data. Guarding it would
        // prevent legitimate cleanup of idle threads (the stub-thread
        // regression tests create threads whose `on_thread_stopped`
        // plants a pending auto_prompt task).
        if thread_view.is_loading_contents {
            return false;
        }
        if let Some(native_thread) = thread_view.as_native_thread(cx) {
            let native = native_thread.read(cx);
            if native.is_generating_title() || native.is_generating_summary() {
                return false;
            }
        }
        if thread_view.has_queued_messages() {
            return false;
        }
        true
    }
}
